/*
 * A262902  a(n) = A049820(A045765(n)); parent-nodes of the leaves of the tree
 *          generated by edge-relation A049820(child) = parent.
 * https://oeis.org/A262902
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = A049820(A045765(n)); A045765 = numbers m not of the form
 *            k - d(k), found by a sieve; A049820(m) = m - d(m)
 * Range:     u8 n <= 85, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 100 terms through n = 9833 (2026-11-07)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>

static uint32_t A049820_a(uint32_t m, const uint32_t *d)
{
    return m - d[m];
}

seq_t a(idx_t n)
{
    if (n < 1) return 0;
    uint64_t L = 4 * (uint64_t)n + 100;
    for (;;) {
        uint64_t s = 1;
        while (s * s <= L) s++;
        uint64_t K = L + 4 * s + 20;
        uint32_t *d = (uint32_t *)calloc(K + 1, sizeof(uint32_t));
        unsigned char *img = (unsigned char *)calloc(L + 1, 1);
        if (!d || !img) { free(d); free(img); return 0; }
        for (uint64_t i = 1; i <= K; i++)
            for (uint64_t j = i; j <= K; j += i) d[j]++;
        for (uint64_t k = 1; k <= K; k++) {
            uint64_t v = k - d[k];
            if (v <= L) img[v] = 1;
        }
        uint64_t cnt = 0;
        seq_t res = 0;
        int found = 0;
        for (uint64_t m = 1; m <= L; m++) {
            if (!img[m]) {
                cnt++;
                if (cnt == (uint64_t)n) {
                    res = (seq_t)A049820_a((uint32_t)m, d);
                    found = 1;
                    break;
                }
            }
        }
        free(d);
        free(img);
        if (found) return res;
        L *= 2;
    }
}
